@Slf4j
@PluginDescriptor(
	name = "Bank Steward",
	description = "Sorts your bank into categories, shows the finished layout instantly and guides you through every move",
	tags = {"bank", "organise", "organize", "sort", "tidy", "tabs", "layout", "category"}
)
@PluginDependency(BankTagsPlugin.class)
public class BankStewardPlugin extends Plugin
{
	static final String PREVIEW_TAG = "banksteward";

	// Messages shared with the Alch Ledger plugin (RuneLite's PluginMessage events)
	private static final String NAMESPACE = "banksteward";
	private static final String ALCH_LEDGER_NAMESPACE = "alchledger";
	private static final String ALCH_LEDGER_CLASS = "com.alchledger.AlchLedgerPlugin";
	private static final int BANK_WIDTH = 8;
	private static final int[] TAB_VARBITS = {
		VarbitID.BANK_TAB_1, VarbitID.BANK_TAB_2, VarbitID.BANK_TAB_3, VarbitID.BANK_TAB_4, VarbitID.BANK_TAB_5,
		VarbitID.BANK_TAB_6, VarbitID.BANK_TAB_7, VarbitID.BANK_TAB_8, VarbitID.BANK_TAB_9};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private BankStewardConfig config;

	@Inject
	private CategoryStore store;

	@Inject
	private MarkerOverlay markerOverlay;

	@Inject
	private GuideOverlay guideOverlay;

	@Inject
	private TagManager tagManager;

	@Inject
	private LayoutManager layoutManager;

	@Inject
	private BankTagsService bankTagsService;

	@Inject
	private EventBus eventBus;

	@Inject
	private PluginManager pluginManager;

	@Getter
	private volatile boolean alchLedgerActive;
	private Map<Integer, Integer> alchProfits = Collections.emptyMap();

	private BankStewardPanel panel;
	private NavigationButton navButton;

	private final Map<Integer, ItemInfo> infoCache = new HashMap<>();
	private volatile Set<Integer> previewItems = Collections.emptySet();
	private boolean dirty = true;
	private boolean wasBankOpen;

	// Read by the overlays, written on the client thread
	@Getter
	private List<BankItem> bankItems = Collections.emptyList();
	private Map<Integer, BankItem> itemsById = Collections.emptyMap();
	@Getter
	private Planner.Plan plan;
	@Getter
	private boolean guideActive;
	@Getter
	private int numTabs;
	private int startOutOfPlace;
	private String lastLoggedView;

	@Provides
	BankStewardConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankStewardConfig.class);
	}

	@Override
	protected void startUp()
	{
		store.load();
		tagManager.registerTag(PREVIEW_TAG, id -> previewItems.contains(id));
		overlayManager.add(markerOverlay);
		overlayManager.add(guideOverlay);

		panel = injector.getInstance(BankStewardPanel.class);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "nav_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Bank Steward")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		updateAlchLedgerActive();
		dirty = true;
		clientThread.invokeLater(this::rebuild);
	}

	@Override
	protected void shutDown()
	{
		clientThread.invokeLater(() ->
		{
			if (PREVIEW_TAG.equals(bankTagsService.getActiveTag()))
			{
				bankTagsService.closeBankTag();
			}
			layoutManager.removeLayout(PREVIEW_TAG);
		});
		tagManager.unregisterTag(PREVIEW_TAG);
		overlayManager.remove(markerOverlay);
		overlayManager.remove(guideOverlay);
		clientToolbar.removeNavigation(navButton);
		setGuideActive(false);
		alchProfits = Collections.emptyMap();
		plan = null;
		bankItems = Collections.emptyList();
		itemsById = Collections.emptyMap();
		infoCache.clear();
		panel = null;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.BANK)
		{
			dirty = true;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int id = event.getVarbitId();
		if (id == VarbitID.BANK_CURRENTTAB || id == VarbitID.BANK_INSERTMODE
			|| id >= VarbitID.BANK_TAB_1 && id <= VarbitID.BANK_TAB_9)
		{
			dirty = true;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (BankStewardConfig.GROUP.equals(event.getGroup())
			|| ALCH_LEDGER_NAMESPACE.equals(event.getGroup()) && config.alchLedgerProfits())
		{
			markDirty();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		boolean open = isBankOpen();
		if (open != wasBankOpen)
		{
			wasBankOpen = open;
			dirty = true;
			if (open && log.isDebugEnabled())
			{
				logTabBar();
			}
		}
		if (dirty)
		{
			rebuild();
		}
	}

	/**
	 * Call from any thread after categories or settings change.
	 */
	void markDirty()
	{
		clientThread.invokeLater(() ->
		{
			dirty = true;
			rebuild();
		});
	}

	boolean isBankOpen()
	{
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		return items != null && !items.isHidden();
	}

	boolean isTagTabOpen()
	{
		return bankTagsService.getActiveTag() != null;
	}

	boolean isPreviewOpen()
	{
		return PREVIEW_TAG.equals(bankTagsService.getActiveTag());
	}

	boolean isInsertMode()
	{
		return client.getVarbitValue(VarbitID.BANK_INSERTMODE) == 1;
	}

	int getViewTab()
	{
		return client.getVarbitValue(VarbitID.BANK_CURRENTTAB);
	}

	private void rebuild()
	{
		dirty = false;
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (bank == null)
		{
			bankItems = Collections.emptyList();
			plan = null;
			pushToPanel();
			return;
		}

		int[] tabSizes = new int[10];
		for (int i = 0; i < 9; i++)
		{
			tabSizes[i + 1] = client.getVarbitValue(TAB_VARBITS[i]);
		}
		int tabs = 0;
		while (tabs < 9 && tabSizes[tabs + 1] > 0)
		{
			tabs++;
		}
		numTabs = tabs;

		List<BankItem> list = new ArrayList<>();
		Item[] items = bank.getItems();
		int tab = 1;
		int tabEnd = tabSizes[1];
		for (int slot = 0; slot < items.length; slot++)
		{
			int id = items[slot].getId();
			if (id < 0)
			{
				break;
			}
			while (tab <= 9 && slot >= tabEnd)
			{
				tab++;
				tabEnd += tab <= 9 ? tabSizes[tab] : 0;
			}
			int itemTab = tab <= 9 ? tab : 0;
			ItemInfo info = info(itemManager.canonicalize(id));
			list.add(new BankItem(slot, id, itemTab, info, store.categorize(info)));
		}
		list = fileProfitableAlchs(list);
		list = sameNameSameCategory(list);
		Map<Integer, BankItem> byId = new HashMap<>();
		for (BankItem b : list)
		{
			byId.put(b.getItemId(), b);
		}
		bankItems = list;
		itemsById = byId;

		plan = Planner.plan(list, tabSizes, getViewTab(), comparator(), config.keepTabIcons());
		logTabOrder(list, getViewTab());
		if (guideActive)
		{
			if (plan.getNext().getType() == Planner.StepType.DONE)
			{
				setGuideActive(false);
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					ColorUtil.wrapWithColorTag("Bank Steward: your bank is in order.", java.awt.Color.GREEN.darker()), null);
			}
			startOutOfPlace = Math.max(startOutOfPlace, plan.getOutOfPlace());
		}
		pushToPanel();
	}

	// ---- Debug logging, to find out why something sorted where it did ----

	/**
	 * Logs the viewed tab's current and wanted order once per bank open or tab change.
	 */
	private void logTabOrder(List<BankItem> items, int viewTab)
	{
		if (!log.isDebugEnabled() || !isBankOpen())
		{
			lastLoggedView = null;
			return;
		}
		String view = viewTab + "/" + items.size();
		if (view.equals(lastLoggedView))
		{
			return;
		}
		lastLoggedView = view;
		List<BankItem> tab = new ArrayList<>();
		for (BankItem b : items)
		{
			if (b.getTab() == viewTab)
			{
				tab.add(b);
			}
		}
		logOrder("Tab " + viewTab + " current order", tab);
		List<BankItem> wanted = new ArrayList<>(tab);
		wanted.sort(comparator());
		logOrder("Tab " + viewTab + " wanted order (before keeping the icon)", wanted);
	}

	private void logOrder(String title, List<BankItem> items)
	{
		if (!log.isDebugEnabled())
		{
			return;
		}
		StringBuilder sb = new StringBuilder(title).append(':');
		for (BankItem b : items)
		{
			ItemInfo i = b.getInfo();
			sb.append("\n  ").append(i.getName())
				.append(" [id ").append(i.getId())
				.append(", ").append(b.getCategory() == null ? "no category" : b.getCategory().getName())
				.append(", ").append(i.getRule())
				.append(i.getRule() == Rule.GEAR
					? ", " + ItemSorter.blockKey(b) + ", style " + ItemSorter.style(i)
					: ", group " + i.getGroup() + ", family " + i.getFamily() + ", rank " + i.getRank())
				.append(']');
		}
		log.debug(sb.toString());
	}

	// ---- Alch Ledger ----

	/**
	 * Starts or stops the guide, and tells Alch Ledger so it can hide its bank outlines while the guide runs.
	 */
	private void setGuideActive(boolean active)
	{
		if (guideActive == active)
		{
			return;
		}
		guideActive = active;
		sendGuideState();
	}

	private void sendGuideState()
	{
		Map<String, Object> data = new HashMap<>();
		data.put("active", guideActive);
		eventBus.post(new PluginMessage(NAMESPACE, "guide", data));
	}

	private void updateAlchLedgerActive()
	{
		boolean active = false;
		for (Plugin p : pluginManager.getPlugins())
		{
			if (ALCH_LEDGER_CLASS.equals(p.getClass().getName()) && pluginManager.isPluginActive(p))
			{
				active = true;
				break;
			}
		}
		if (active != alchLedgerActive)
		{
			alchLedgerActive = active;
			markDirty();
		}
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		updateAlchLedgerActive();
	}

	@Subscribe
	public void onPluginMessage(PluginMessage message)
	{
		if (!ALCH_LEDGER_NAMESPACE.equals(message.getNamespace()))
		{
			return;
		}
		if ("hello".equals(message.getName()))
		{
			// Alch Ledger just started: tell it whether the guide is running
			sendGuideState();
		}
		else if ("profits".equals(message.getName()))
		{
			Object raw = message.getData().get("profits");
			Map<Integer, Integer> profits = new HashMap<>();
			if (raw instanceof Map)
			{
				for (Map.Entry<?, ?> e : ((Map<?, ?>) raw).entrySet())
				{
					if (e.getKey() instanceof Integer && e.getValue() instanceof Integer)
					{
						profits.put((Integer) e.getKey(), (Integer) e.getValue());
					}
				}
			}
			alchProfits = profits;
		}
	}

	/**
	 * With the setting on and Alch Ledger running, items it shows as profitable go in the High alch category,
	 * unless the player has filed them by hand. Alch Ledger answers the request straight away, on this thread.
	 */
	private List<BankItem> fileProfitableAlchs(List<BankItem> items)
	{
		alchProfits = Collections.emptyMap();
		Category highAlch = store.get(CategoryStore.HIGH_ALCH);
		if (!config.alchLedgerProfits() || !alchLedgerActive || highAlch == null || items.isEmpty())
		{
			return items;
		}

		List<Integer> ids = new ArrayList<>();
		for (BankItem b : items)
		{
			ids.add(b.getInfo().getId());
		}
		Map<String, Object> data = new HashMap<>();
		data.put("items", ids);
		eventBus.post(new PluginMessage(NAMESPACE, "profitRequest", data));

		Map<Integer, Integer> profits = alchProfits;
		if (profits.isEmpty())
		{
			return items;
		}
		List<BankItem> out = new ArrayList<>(items.size());
		for (BankItem b : items)
		{
			int id = b.getInfo().getId();
			boolean file = profits.containsKey(id) && !store.hasOverride(id);
			out.add(file ? new BankItem(b.getSlot(), b.getItemId(), b.getTab(), b.getInfo(), highAlch) : b);
		}
		return out;
	}

	/**
	 * Items with exactly the same name share one category: a hand-picked one if any of them has it,
	 * otherwise the one with the lowest id.
	 */
	private List<BankItem> sameNameSameCategory(List<BankItem> items)
	{
		Map<String, BankItem> chosen = new HashMap<>();
		for (BankItem b : items)
		{
			String name = b.getInfo().getName().toLowerCase();
			BankItem current = chosen.get(name);
			boolean override = store.hasOverride(b.getInfo().getId());
			if (current == null
				|| override && !store.hasOverride(current.getInfo().getId())
				|| override == store.hasOverride(current.getInfo().getId()) && b.getInfo().getId() < current.getInfo().getId())
			{
				chosen.put(name, b);
			}
		}
		List<BankItem> out = new ArrayList<>(items.size());
		for (BankItem b : items)
		{
			Category c = chosen.get(b.getInfo().getName().toLowerCase()).getCategory();
			out.add(c == b.getCategory() ? b : new BankItem(b.getSlot(), b.getItemId(), b.getTab(), b.getInfo(), c));
		}
		return out;
	}

	private Comparator<BankItem> comparator()
	{
		Map<String, Integer> order = new HashMap<>();
		List<Category> categories = store.getCategories();
		for (int i = 0; i < categories.size(); i++)
		{
			order.put(categories.get(i).getId(), i);
		}
		return ItemSorter.comparator(order, config.gearSort(), bankItems, alchProfits);
	}

	private ItemInfo info(int id)
	{
		ItemInfo cached = infoCache.get(id);
		if (cached != null)
		{
			return cached;
		}
		ItemComposition comp = itemManager.getItemComposition(id);
		ItemStats stats = itemManager.getItemStats(id);
		boolean equipable = stats != null && stats.isEquipable();
		ItemInfo info = ItemRules.classify(id, comp.getName(), equipable,
			stats != null ? stats.getEquipment() : null, comp.getInventoryActions(), comp.getPrice());
		infoCache.put(id, info);
		return info;
	}

	private void pushToPanel()
	{
		if (panel == null)
		{
			return;
		}
		BankStewardPanel.Status status = new BankStewardPanel.Status();
		status.bankKnown = client.getItemContainer(InventoryID.BANK) != null;
		status.bankOpen = isBankOpen();
		status.guideActive = guideActive;
		status.previewOpen = isPreviewOpen();
		status.tagTabOpen = isTagTabOpen() && !status.previewOpen;
		status.insertMode = isInsertMode();
		status.total = bankItems.size();
		status.outOfPlace = plan != null ? plan.getOutOfPlace() : 0;
		status.startOutOfPlace = startOutOfPlace;
		status.instruction = plan != null ? describe(plan.getNext()) : null;
		status.reorderStep = plan != null && plan.getNext().getType() == Planner.StepType.REORDER;
		status.warnings = plan != null ? plan.getWarnings() : Collections.emptyList();
		Map<String, Integer> counts = new HashMap<>();
		int unassigned = 0;
		for (BankItem b : bankItems)
		{
			if (b.getCategory() == null)
			{
				unassigned++;
			}
			else
			{
				counts.merge(b.getCategory().getId(), 1, Integer::sum);
			}
		}
		status.counts = counts;
		status.unassigned = unassigned;
		BankStewardPanel p = panel;
		SwingUtilities.invokeLater(() -> p.update(status));
	}

	String describe(Planner.Step step)
	{
		switch (step.getType())
		{
			case MOVE_TO_TAB:
				String name = step.getItem().getInfo().getName();
				if (step.getTab() == 0)
				{
					return "Drag " + name + " onto the All tab (the first tab) to take it out of its tab.";
				}
				if (step.isNewTab())
				{
					return "Drag " + name + " onto the empty tab slot (+) to make tab " + step.getTab() + ".";
				}
				return "Drag " + name + " onto tab " + step.getTab() + ".";
			case REORDER:
				BankItem target = itemAtSlot(step.getTargetSlot());
				return "Drag " + step.getItem().getInfo().getName() + " onto "
					+ (target != null ? target.getInfo().getName() : "the highlighted slot") + ".";
			case OPEN_TAB:
				if (plan != null && !plan.getWrongTab().isEmpty())
				{
					return "Open the All tab so you can move items between tabs.";
				}
				return step.getTab() == 0
					? "Open the All tab and scroll to the untabbed items at the bottom."
					: "Open tab " + step.getTab() + " to put it in order.";
			default:
				return "Your bank is in order.";
		}
	}

	BankItem itemById(int itemId)
	{
		return itemsById.get(itemId);
	}

	BankItem itemAtSlot(int slot)
	{
		List<BankItem> items = bankItems;
		return slot >= 0 && slot < items.size() ? items.get(slot) : null;
	}

	// ---- Panel actions (Swing thread) ----

	void toggleGuide()
	{
		clientThread.invokeLater(() ->
		{
			setGuideActive(!guideActive);
			startOutOfPlace = plan != null ? plan.getOutOfPlace() : 0;
			if (guideActive && isPreviewOpen())
			{
				bankTagsService.closeBankTag();
			}
			rebuild();
		});
	}

	void togglePreview()
	{
		clientThread.invokeLater(() ->
		{
			if (isPreviewOpen())
			{
				bankTagsService.closeBankTag();
			}
			else if (isBankOpen())
			{
				openPreview();
			}
			pushToPanel();
		});
	}

	/**
	 * Shows the whole bank already organised, as a Bank Tags layout: one block per category, each starting on a new row.
	 */
	private void openPreview()
	{
		List<BankItem> sorted = new ArrayList<>(bankItems);
		sorted.sort(comparator());
		logOrder("Preview order", sorted);
		List<Integer> layout = new ArrayList<>();
		Set<Integer> ids = new HashSet<>();
		String lastCategory = null;
		for (BankItem b : sorted)
		{
			String cat = b.getCategory() == null ? "" : b.getCategory().getId();
			if (lastCategory != null && !cat.equals(lastCategory))
			{
				while (layout.size() % BANK_WIDTH != 0)
				{
					layout.add(-1);
				}
			}
			lastCategory = cat;
			layout.add(b.getInfo().getId());
			ids.add(b.getInfo().getId());
			ids.add(b.getItemId());
		}
		previewItems = ids;
		int[] arr = layout.stream().mapToInt(Integer::intValue).toArray();
		layoutManager.saveLayout(new Layout(PREVIEW_TAG, arr));
		setGuideActive(false);
		bankTagsService.openBankTag(PREVIEW_TAG, 0);
	}

	// ---- Right-click menus ----

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.categoryMenu())
		{
			return;
		}
		String option = Text.removeTags(event.getOption());
		if (event.getActionParam1() == InterfaceID.Bankmain.ITEMS && "Examine".equals(option))
		{
			addItemMenu(event);
		}
		else if (event.getActionParam1() == InterfaceID.Bankmain.TABS
			&& (option.startsWith("View tab") || option.equals("View all items")))
		{
			int tab = tabForHeader(event.getActionParam0());
			if (tab >= 0)
			{
				addTabMenu(event, tab);
			}
		}
	}

	private void addItemMenu(MenuEntryAdded event)
	{
		int rawId = event.getItemId();
		if (rawId <= 0)
		{
			return;
		}
		int id = itemManager.canonicalize(rawId);
		Category current = store.categorize(info(id));
		boolean overridden = store.hasOverride(id);

		MenuEntry parent = client.getMenu().createMenuEntry(-1)
			.setOption(ColorUtil.wrapWithColorTag("Steward", java.awt.Color.ORANGE))
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE);
		Menu sub = parent.createSubMenu();

		List<Category> categories = store.getCategories();
		Collections.reverse(categories);
		sub.createMenuEntry(-1)
			.setOption("Leave where it is")
			.setType(MenuAction.RUNELITE)
			.onClick(e -> setCategory(id, CategoryStore.KEEP));
		if (overridden)
		{
			sub.createMenuEntry(-1)
				.setOption("Automatic")
				.setType(MenuAction.RUNELITE)
				.onClick(e -> setCategory(id, null));
		}
		for (Category c : categories)
		{
			boolean selected = current != null && current.getId().equals(c.getId());
			sub.createMenuEntry(-1)
				.setOption(ColorUtil.wrapWithColorTag(c.getName(), c.getColor()) + (selected ? " (current)" : ""))
				.setType(MenuAction.RUNELITE)
				.onClick(e -> setCategory(id, c.getId()));
		}
	}

	private void setCategory(int itemId, String categoryId)
	{
		// every item with the same name goes with it
		Set<Integer> ids = new HashSet<>();
		ids.add(itemId);
		String name = info(itemId).getName();
		for (BankItem b : bankItems)
		{
			if (b.getInfo().getName().equalsIgnoreCase(name))
			{
				ids.add(b.getInfo().getId());
			}
		}
		store.setOverrides(ids, categoryId);
		markDirty();
		refreshPanelCategories();
	}

	private void addTabMenu(MenuEntryAdded event, int tab)
	{
		List<Category> categories = store.getCategories();
		Collections.reverse(categories);
		String tabName = Category.tabLabel(tab);

		MenuEntry fileAs = client.getMenu().createMenuEntry(-1)
			.setOption(ColorUtil.wrapWithColorTag("Steward: file all items as", java.awt.Color.ORANGE))
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE);
		Menu fileSub = fileAs.createSubMenu();
		for (Category c : categories)
		{
			fileSub.createMenuEntry(-1)
				.setOption(ColorUtil.wrapWithColorTag(c.getName(), c.getColor()))
				.setType(MenuAction.RUNELITE)
				.onClick(e -> fileTabAs(tab, c.getId()));
		}

		MenuEntry assign = client.getMenu().createMenuEntry(-1)
			.setOption(ColorUtil.wrapWithColorTag("Steward: use " + tabName + " for", java.awt.Color.ORANGE))
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE);
		Menu assignSub = assign.createSubMenu();
		for (Category c : categories)
		{
			assignSub.createMenuEntry(-1)
				.setOption(ColorUtil.wrapWithColorTag(c.getName(), c.getColor()) + (c.getTab() == tab ? " (current)" : ""))
				.setType(MenuAction.RUNELITE)
				.onClick(e ->
				{
					c.setTab(tab);
					store.update(c);
					markDirty();
					refreshPanelCategories();
				});
		}
	}

	private void fileTabAs(int tab, String categoryId)
	{
		List<Integer> ids = new ArrayList<>();
		for (BankItem b : bankItems)
		{
			if (b.getTab() == tab)
			{
				ids.add(b.getInfo().getId());
			}
		}
		store.setOverrides(ids, categoryId);
		markDirty();
		refreshPanelCategories();
	}

	private void refreshPanelCategories()
	{
		BankStewardPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(p::rebuildCategories);
		}
	}

	// ---- Tab headers ----

	/**
	 * Bank tab header widgets: index 0 is the All tab, 1-9 the tabs, and 10 the empty "New tab" slot.
	 * Found by their menu options; hidden ones are kept so callers can check. The tab bar children are
	 * normally 10 (All), 11-19 (tabs) and the New tab slot after the last tab, which is the fallback.
	 */
	Widget[] tabHeaders()
	{
		Widget[] headers = new Widget[11];
		Widget bar = client.getWidget(InterfaceID.Bankmain.TABS);
		Widget[] children = bar == null ? null : bar.getDynamicChildren();
		if (children == null)
		{
			return headers;
		}

		List<Widget> tabs = new ArrayList<>();
		for (Widget w : children)
		{
			String[] actions = w.getActions();
			if (actions == null)
			{
				continue;
			}
			for (String a : actions)
			{
				if ("View all items".equals(a))
				{
					headers[0] = w;
					break;
				}
				if ("View tab".equals(a))
				{
					tabs.add(w);
					break;
				}
				if ("New tab".equals(a))
				{
					headers[10] = w;
					break;
				}
			}
		}

		if (headers[0] == null && tabs.isEmpty())
		{
			for (int t = 0; t <= numTabs && 10 + t < children.length; t++)
			{
				headers[t] = children[10 + t];
			}
			if (numTabs < 9 && 11 + numTabs < children.length)
			{
				headers[10] = children[11 + numTabs];
			}
			return headers;
		}

		// tabs are listed in order, so child index gives tab number
		tabs.sort(Comparator.comparingInt(Widget::getIndex));
		for (int i = 0; i < tabs.size() && i < 9; i++)
		{
			headers[i + 1] = tabs.get(i);
		}
		return headers;
	}

	/**
	 * Screen bounds of a visible tab header, or null. numTabs+1 is the New tab slot.
	 */
	java.awt.Rectangle tabBounds(int tab)
	{
		Widget[] headers = tabHeaders();
		Widget w = null;
		if (tab >= 0 && tab <= numTabs)
		{
			w = headers[tab];
		}
		else if (tab == numTabs + 1)
		{
			w = headers[10];
		}
		if (w == null || w.isHidden() || w.getBounds().x < 0)
		{
			return null;
		}
		return w.getBounds();
	}

	private void logTabBar()
	{
		Widget bar = client.getWidget(InterfaceID.Bankmain.TABS);
		Widget[] children = bar == null ? null : bar.getDynamicChildren();
		if (children == null)
		{
			return;
		}
		for (Widget w : children)
		{
			if (w.getActions() != null)
			{
				log.debug("Tab bar child {} at {}: {}", w.getIndex(), w.getBounds(), java.util.Arrays.toString(w.getActions()));
			}
		}
	}

	private int tabForHeader(int childIndex)
	{
		Widget[] headers = tabHeaders();
		for (int t = 0; t <= numTabs; t++)
		{
			if (headers[t] != null && headers[t].getIndex() == childIndex)
			{
				return t;
			}
		}
		return -1;
	}

	Widget itemWidget(int slot)
	{
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		return items == null ? null : items.getChild(slot);
	}
}

package com.banksteward;

import java.awt.Color;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * A user-editable item category. Saved as JSON in the plugin config.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class Category
{
	static final int NO_TAB = -1;
	static final int MAIN_TAB = 0;

	/**
	 * Stable id. Built-in categories use their rule name (e.g. "gear"), user ones start with "c".
	 */
	private String id;
	private String name;
	private int rgb;
	/**
	 * -1 for none (items stay where they are), 0 for the main tab, 1-9 for bank tabs.
	 */
	private int tab;
	/**
	 * Comma-separated name patterns, * is a wildcard. Checked before the built-in rules.
	 */
	private String patterns;

	Color getColor()
	{
		return new Color(rgb);
	}

	void setColor(Color color)
	{
		rgb = color.getRGB() & 0xFFFFFF;
	}

	static String tabLabel(int tab)
	{
		if (tab == NO_TAB)
		{
			return "None";
		}
		return tab == MAIN_TAB ? "Main" : "Tab " + tab;
	}
}

package com.banksteward;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Categories, per-item overrides, and working out which category an item is in.
 * Methods are synchronized because the panel edits from the Swing thread while the client thread reads.
 */
@Slf4j
@Singleton
class CategoryStore
{
	/**
	 * Override value for "leave this item where it is".
	 */
	static final String KEEP = "keep";

	/**
	 * The High alch category. It has no tab by default, so nothing moves until the player gives it one.
	 */
	static final String HIGH_ALCH = "highalch";
	private static final String HIGH_ALCH_ADDED_KEY = "highAlchAdded";

	private final ConfigManager configManager;
	private final Gson gson;

	private List<Category> categories = new ArrayList<>();
	private final Map<Integer, String> overrides = new HashMap<>();
	private final Map<String, List<Pattern>> compiledPatterns = new HashMap<>();

	@Inject
	CategoryStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	synchronized void load()
	{
		categories = new ArrayList<>();
		String json = configManager.getConfiguration(BankStewardConfig.GROUP, BankStewardConfig.CATEGORIES_KEY);
		if (json != null && !json.isEmpty())
		{
			try
			{
				List<Category> loaded = gson.fromJson(json, new TypeToken<List<Category>>()
				{
				}.getType());
				if (loaded != null)
				{
					categories.addAll(loaded);
				}
			}
			catch (JsonSyntaxException e)
			{
				log.warn("Couldn't read saved categories, using defaults", e);
			}
		}
		if (categories.isEmpty())
		{
			categories = defaults();
		}
		else if (configManager.getConfiguration(BankStewardConfig.GROUP, HIGH_ALCH_ADDED_KEY) == null
			&& categories.stream().noneMatch(c -> HIGH_ALCH.equals(c.getId())))
		{
			// saved before High alch existed: add it once, at the bottom (a player can still delete it)
			categories.add(highAlch());
		}
		configManager.setConfiguration(BankStewardConfig.GROUP, HIGH_ALCH_ADDED_KEY, true);

		overrides.clear();
		String saved = configManager.getConfiguration(BankStewardConfig.GROUP, BankStewardConfig.OVERRIDES_KEY);
		if (saved != null && !saved.isEmpty())
		{
			for (String pair : saved.split(","))
			{
				int colon = pair.indexOf(':');
				if (colon <= 0)
				{
					continue;
				}
				try
				{
					overrides.put(Integer.parseInt(pair.substring(0, colon)), pair.substring(colon + 1));
				}
				catch (NumberFormatException ignored)
				{
				}
			}
		}
		compilePatterns();
	}

	private static List<Category> defaults()
	{
		List<Category> list = new ArrayList<>();
		for (Rule rule : Rule.values())
		{
			list.add(rule.toCategory());
		}
		list.add(highAlch());
		return list;
	}

	private static Category highAlch()
	{
		return new Category(HIGH_ALCH, "High alch", 0xFF8C42, Category.NO_TAB, "");
	}

	private void save()
	{
		configManager.setConfiguration(BankStewardConfig.GROUP, BankStewardConfig.CATEGORIES_KEY, gson.toJson(categories));
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<Integer, String> e : overrides.entrySet())
		{
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(e.getKey()).append(':').append(e.getValue());
		}
		configManager.setConfiguration(BankStewardConfig.GROUP, BankStewardConfig.OVERRIDES_KEY, sb.toString());
		compilePatterns();
	}

	private void compilePatterns()
	{
		compiledPatterns.clear();
		for (Category c : categories)
		{
			if (c.getPatterns() == null || c.getPatterns().trim().isEmpty())
			{
				continue;
			}
			List<Pattern> list = new ArrayList<>();
			for (String p : c.getPatterns().split(","))
			{
				String t = p.trim().toLowerCase();
				if (t.isEmpty())
				{
					continue;
				}
				StringBuilder regex = new StringBuilder();
				for (String part : t.split("\\*", -1))
				{
					if (regex.length() > 0 || t.startsWith("*"))
					{
						regex.append(".*");
					}
					regex.append(Pattern.quote(part));
				}
				list.add(Pattern.compile(regex.toString()));
			}
			compiledPatterns.put(c.getId(), list);
		}
	}


	synchronized List<Category> getCategories()
	{
		List<Category> copy = new ArrayList<>();
		for (Category c : categories)
		{
			copy.add(new Category(c.getId(), c.getName(), c.getRgb(), c.getTab(), c.getPatterns()));
		}
		return copy;
	}

	synchronized Category get(String id)
	{
		for (Category c : categories)
		{
			if (c.getId().equals(id))
			{
				return c;
			}
		}
		return null;
	}


	/**
	 * The category an item is in: a manual choice first, then name patterns, then the built-in rule.
	 * Returns null if the item fits no category.
	 */
	synchronized Category categorize(ItemInfo info)
	{
		String override = overrides.get(info.getId());
		if (KEEP.equals(override))
		{
			return null;
		}
		if (override != null)
		{
			Category c = get(override);
			if (c != null)
			{
				return c;
			}
		}

		String lower = info.getName().toLowerCase();
		for (Category c : categories)
		{
			List<Pattern> patterns = compiledPatterns.get(c.getId());
			if (patterns == null)
			{
				continue;
			}
			for (Pattern p : patterns)
			{
				if (p.matcher(lower).matches())
				{
					return c;
				}
			}
		}

		Category c = get(info.getRule().getId());
		return c != null ? c : get(Rule.MISC.getId());
	}

	synchronized boolean hasOverride(int itemId)
	{
		return overrides.containsKey(itemId);
	}

	synchronized void setOverride(int itemId, String categoryId)
	{
		if (categoryId == null)
		{
			overrides.remove(itemId);
		}
		else
		{
			overrides.put(itemId, categoryId);
		}
		save();
	}

	synchronized void setOverrides(Iterable<Integer> itemIds, String categoryId)
	{
		for (int id : itemIds)
		{
			if (categoryId == null)
			{
				overrides.remove(id);
			}
			else
			{
				overrides.put(id, categoryId);
			}
		}
		save();
	}

	synchronized void update(Category changed)
	{
		for (int i = 0; i < categories.size(); i++)
		{
			if (categories.get(i).getId().equals(changed.getId()))
			{
				categories.set(i, changed);
				save();
				return;
			}
		}
	}

	synchronized Category add(String name)
	{
		// spread new colours round the hue wheel
		float hue = (categories.size() * 0.13f) % 1f;
		Category c = new Category("c" + System.currentTimeMillis(), name,
			java.awt.Color.HSBtoRGB(hue, 0.6f, 0.95f) & 0xFFFFFF, Category.NO_TAB, "");
		categories.add(c);
		save();
		return c;
	}

	synchronized void remove(String id)
	{
		categories.removeIf(c -> c.getId().equals(id));
		overrides.values().removeIf(id::equals);
		save();
	}

	private int indexOf(String id)
	{
		for (int i = 0; i < categories.size(); i++)
		{
			if (categories.get(i).getId().equals(id))
			{
				return i;
			}
		}
		return Integer.MAX_VALUE;
	}

	synchronized void move(String id, int delta)
	{
		int i = indexOf(id);
		int j = i + delta;
		if (i == Integer.MAX_VALUE || j < 0 || j >= categories.size())
		{
			return;
		}
		Collections.swap(categories, i, j);
		save();
	}

	synchronized void resetToDefaults()
	{
		categories = defaults();
		overrides.clear();
		save();
	}
}

package com.banksteward;

import java.awt.Color;

/**
 * Softens overlay colours so markers and highlights don't glare over the bank.
 */
final class Fade
{
	private static final float AMOUNT = 0.7f;

	private Fade()
	{
	}

	/**
	 * A category colour at the player's chosen opacity (percent).
	 */
	static Color category(Color c, int percent)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.round(255 * percent / 100f));
	}

	static Color of(Color c)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.round(c.getAlpha() * AMOUNT));
	}
}

package com.banksteward;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.awt.geom.AffineTransform;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Tab header colours, and the guide's "move this here" highlights with an arrow between them.
 */
class GuideOverlay extends Overlay
{
	private static final Stroke THICK = new BasicStroke(2f);
	private static final Stroke ARROW = new BasicStroke(2.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final Color WARNING = new Color(255, 70, 70);

	// Alch Ledger outlines items in yellow, green, blue, purple and red, so with it on the default guide
	// colours could pass for a tier outline. These stand apart from all of them.
	private static final Color DEFAULT_MOVE = new Color(80, 230, 100, 230);
	private static final Color DEFAULT_TARGET = new Color(255, 210, 60, 230);
	private static final Color ALCH_SAFE_MOVE = new Color(245, 245, 245, 235);
	private static final Color ALCH_SAFE_TARGET = new Color(255, 120, 230, 235);

	private final Client client;
	private final BankStewardPlugin plugin;
	private final BankStewardConfig config;
	private final CategoryStore store;

	@Inject
	GuideOverlay(Client client, BankStewardPlugin plugin, BankStewardConfig config, CategoryStore store)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.store = store;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!plugin.isBankOpen() || plugin.isTagTabOpen())
		{
			return null;
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		if (config.tabColours())
		{
			drawTabColours(g);
		}

		Planner.Plan plan = plugin.getPlan();
		if (!plugin.isGuideActive() || plan == null)
		{
			return null;
		}

		Planner.Step step = plan.getNext();
		switch (step.getType())
		{
			case MOVE_TO_TAB:
				drawMove(g, step.getItem(), plugin.tabBounds(step.getTab()), step.isNewTab() ? "NEW TAB" : "DROP");
				break;
			case REORDER:
				if (!plugin.isInsertMode())
				{
					drawInsertWarning(g);
					break;
				}
				Widget target = visibleItem(step.getTargetSlot());
				if (target != null)
				{
					drawMove(g, step.getItem(), target.getBounds(), "HERE");
				}
				else
				{
					drawMoveOffscreen(g, step.getItem(), step.getTargetSlot());
				}
				break;
			case OPEN_TAB:
				Rectangle tab = plugin.tabBounds(step.getTab());
				if (tab != null)
				{
					drawBox(g, tab, pulse(targetColour()), "OPEN");
				}
				break;
			default:
				break;
		}
		return null;
	}

	private void drawTabColours(Graphics2D g)
	{
		Widget[] headers = plugin.tabHeaders();
		List<Category> categories = store.getCategories();
		for (int t = 0; t <= plugin.getNumTabs(); t++)
		{
			if (headers[t] == null || headers[t].isHidden() || headers[t].getBounds().x < 0)
			{
				continue;
			}
			Rectangle r = headers[t].getBounds();
			int x = r.x + 3;
			int width = r.width - 6;
			// several categories can share a tab: split the bar between them
			int n = 0;
			for (Category c : categories)
			{
				if (c.getTab() == t)
				{
					n++;
				}
			}
			int i = 0;
			for (Category c : categories)
			{
				if (c.getTab() != t)
				{
					continue;
				}
				int x0 = x + width * i / n;
				int x1 = x + width * (i + 1) / n;
				g.setColor(Fade.category(c.getColor(), config.categoryOpacity()));
				g.fillRect(x0, r.y + r.height - 4, x1 - x0, 3);
				i++;
			}
		}
	}

	private void drawMove(Graphics2D g, BankItem item, Rectangle target, String targetLabel)
	{
		Color move = moveColour();
		Color drop = pulse(targetColour());

		// While the item is being dragged, the arrow starts from the mouse. Dragging can scroll the
		// item itself out of view, so the target has to show either way.
		Rectangle from = null;
		boolean dragging = isDragging(item);
		if (dragging)
		{
			net.runelite.api.Point mouse = client.getMouseCanvasPosition();
			from = new Rectangle(mouse.getX() - 8, mouse.getY() - 8, 16, 16);
		}
		else
		{
			Widget source = visibleItem(item.getSlot());
			if (source != null)
			{
				from = source.getBounds();
			}
		}

		if (from != null && target != null && config.showArrow())
		{
			drawArrow(g, from, target, move);
		}
		if (from != null && !dragging)
		{
			drawBox(g, from, move, "MOVE");
		}
		if (target != null)
		{
			drawBox(g, target, drop, targetLabel);
		}
		if (from == null)
		{
			drawHint(g, "Scroll to find " + item.getInfo().getName());
		}
	}

	private boolean isDragging(BankItem item)
	{
		if (!client.isDraggingWidget())
		{
			return false;
		}
		Widget dragged = client.getDraggedWidget();
		return dragged != null && dragged.getId() == InterfaceID.Bankmain.ITEMS && dragged.getIndex() == item.getSlot();
	}

	/**
	 * The drop target is scrolled out of view. Holding a dragged item at the edge of the bank scrolls it,
	 * so point at that edge, in the target's column, until the target comes into view.
	 */
	private void drawMoveOffscreen(Graphics2D g, BankItem item, int targetSlot)
	{
		Widget w = plugin.itemWidget(targetSlot);
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (w == null || w.isHidden() || container == null)
		{
			drawMove(g, item, null, "HERE");
			return;
		}
		Rectangle view = container.getBounds();
		Rectangle r = w.getBounds();
		boolean above = r.y < view.y;
		Rectangle edge = new Rectangle(r.x, above ? view.y : view.y + view.height - r.height, r.width, r.height);
		drawMove(g, item, edge, above ? "DRAG UP" : "DRAG DOWN");

		BankItem target = plugin.itemAtSlot(targetSlot);
		String name = target != null ? target.getInfo().getName() : "the target";
		drawHint(g, "Hold it at the " + (above ? "top" : "bottom") + " edge to scroll to " + name, !above);
	}

	private void drawInsertWarning(Graphics2D g)
	{
		Widget button = client.getWidget(InterfaceID.Bankmain.SWAP_INSERT);
		if (button != null && !button.isHidden())
		{
			drawBox(g, button.getBounds(), pulse(WARNING), "INSERT");
		}
		drawHint(g, "Switch the bank to Insert mode");
	}

	/**
	 * The item's widget, if it's on screen inside the scrolling item area.
	 */
	private Widget visibleItem(int slot)
	{
		Widget w = plugin.itemWidget(slot);
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (w == null || w.isHidden() || container == null)
		{
			return null;
		}
		Rectangle view = container.getBounds();
		Rectangle r = w.getBounds();
		if (r.y < view.y - r.height / 2 || r.y + r.height > view.y + view.height + r.height / 2)
		{
			return null;
		}
		return w;
	}

	private void drawBox(Graphics2D g, Rectangle r, Color c, String label)
	{
		g.setStroke(THICK);
		g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.min(40, c.getAlpha())));
		g.fillRect(r.x, r.y, r.width, r.height);
		g.setColor(Fade.of(c));
		g.drawRect(r.x, r.y, r.width, r.height);

		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();
		int w = fm.stringWidth(label) + 4;
		int x = r.x + (r.width - w) / 2;
		int y = r.y - fm.getHeight() - 1;
		g.setColor(new Color(0, 0, 0, 190));
		g.fillRect(x, y, w, fm.getHeight());
		g.setColor(c);
		g.drawString(label, x + 2, y + fm.getAscent());
	}

	private void drawHint(Graphics2D g, String text)
	{
		drawHint(g, text, true);
	}

	private void drawHint(Graphics2D g, String text, boolean top)
	{
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (container == null)
		{
			return;
		}
		Rectangle view = container.getBounds();
		g.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics fm = g.getFontMetrics();
		int w = fm.stringWidth(text) + 12;
		int x = view.x + (view.width - w) / 2;
		int y = top ? view.y + 6 : view.y + view.height - fm.getHeight() - 12;
		g.setColor(new Color(0, 0, 0, 200));
		g.fillRoundRect(x, y, w, fm.getHeight() + 6, 6, 6);
		g.setColor(targetColour());
		g.drawString(text, x + 6, y + 3 + fm.getAscent());
	}

	private void drawArrow(Graphics2D g, Rectangle from, Rectangle to, Color c)
	{
		double x1 = from.getCenterX(), y1 = from.getCenterY();
		double x2 = to.getCenterX(), y2 = to.getCenterY();
		double len = Math.hypot(x2 - x1, y2 - y1);
		if (len < 20)
		{
			return;
		}
		// stop short of both boxes
		double ux = (x2 - x1) / len, uy = (y2 - y1) / len;
		double start = 14, end = 16;
		int sx = (int) (x1 + ux * start), sy = (int) (y1 + uy * start);
		int ex = (int) (x2 - ux * end), ey = (int) (y2 - uy * end);

		g.setStroke(ARROW);
		g.setColor(new Color(0, 0, 0, 100));
		g.drawLine(sx + 1, sy + 1, ex + 1, ey + 1);
		g.setColor(Fade.of(c));
		g.drawLine(sx, sy, ex, ey);

		AffineTransform old = g.getTransform();
		g.translate(ex, ey);
		g.rotate(Math.atan2(uy, ux));
		Polygon head = new Polygon(new int[]{4, -7, -7}, new int[]{0, -6, 6}, 3);
		g.fillPolygon(head);
		g.setTransform(old);
	}

	/**
	 * The guide colours, swapped for ones Alch Ledger doesn't use when it's on and the player kept the defaults.
	 */
	private Color moveColour()
	{
		Color c = config.moveColour();
		return plugin.isAlchLedgerActive() && c.equals(DEFAULT_MOVE) ? ALCH_SAFE_MOVE : c;
	}

	private Color targetColour()
	{
		Color c = config.targetColour();
		return plugin.isAlchLedgerActive() && c.equals(DEFAULT_TARGET) ? ALCH_SAFE_TARGET : c;
	}

	private static Color pulse(Color c)
	{
		double t = (System.currentTimeMillis() % 1200) / 1200.0;
		double f = 0.55 + 0.45 * (0.5 + 0.5 * Math.sin(t * 2 * Math.PI));
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), (int) (c.getAlpha() * f));
	}
}

package com.banksteward;

import lombok.Value;
import net.runelite.client.game.ItemEquipmentStats;

/**
 * Everything the categoriser and sorter need about one item, worked out once on the client thread.
 */
@Value
class ItemInfo
{
	int id;
	String name;
	/**
	 * Lower-case name without a trailing "(4)", "(p++)" and so on, so doses and charges group together.
	 */
	String baseName;
	/**
	 * The number in a trailing "(n)" (dose, charges), or 0.
	 */
	int suffixNumber;
	Rule rule;
	/**
	 * Sort group inside the rule (e.g. runes before ammo).
	 */
	int group;
	/**
	 * Sort rank inside the group, lowest first.
	 */
	int rank;
	int storePrice;
	ItemEquipmentStats stats;
	/**
	 * Main word of the name ("cannonball", "hat") for categories without their own order, so items
	 * with similar names sit together. Empty when the category has its own order.
	 */
	String family;
}

