	private ItemRules()
	{
	}

	static String baseName(String lowerName)
	{
		return SUFFIX.matcher(lowerName).replaceAll("").trim();
	}

	static int suffixNumber(String lowerName)
	{
		Matcher m = NUMBER_SUFFIX.matcher(lowerName);
		return m.find() ? Integer.parseInt(m.group(1)) : 0;
	}

	static boolean hasCombatStats(ItemEquipmentStats s)
	{
		return s != null && (s.getAstab() != 0 || s.getAslash() != 0 || s.getAcrush() != 0 || s.getAmagic() != 0
			|| s.getArange() != 0 || s.getDstab() != 0 || s.getDslash() != 0 || s.getDcrush() != 0
			|| s.getDmagic() != 0 || s.getDrange() != 0 || s.getStr() != 0 || s.getRstr() != 0
			|| s.getMdmg() != 0 || s.getPrayer() != 0);
	}

	private static boolean startsWithAny(String s, List<String> list)
	{
		for (String p : list)
		{
			if (s.startsWith(p))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Which outfit an item belongs to: the longest matching name, so "spirit angler" isn't filed under "angler".
	 */
	private static int outfitSet(String n)
	{
		int best = -1;
		for (int i = 0; i < OUTFITS.size(); i++)
		{
			if (n.contains(OUTFITS.get(i)) && (best < 0 || OUTFITS.get(i).length() > OUTFITS.get(best).length()))
			{
				best = i;
			}
		}
		return best;
	}

	private static int outfitPiece(int slot)
	{
		if (slot == EquipmentInventorySlot.HEAD.getSlotIdx())
		{
			return 0;
		}
		if (slot == EquipmentInventorySlot.CAPE.getSlotIdx())
		{
			return 1;
		}
		if (slot == EquipmentInventorySlot.AMULET.getSlotIdx())
		{
			return 2;
		}
		if (slot == EquipmentInventorySlot.BODY.getSlotIdx())
		{
			return 3;
		}
		if (slot == EquipmentInventorySlot.LEGS.getSlotIdx())
		{
			return 4;
		}
		if (slot == EquipmentInventorySlot.GLOVES.getSlotIdx())
		{
			return 5;
		}
		if (slot == EquipmentInventorySlot.BOOTS.getSlotIdx())
		{
			return 6;
		}
		return 7;
	}

	private static boolean containsAny(String s, List<String> list)
	{
		for (String p : list)
		{
			if (s.contains(p))
			{
				return true;
			}
		}
		return false;
	}

	private static int indexOf(String[] order, String s)
	{
		for (int i = 0; i < order.length; i++)
		{
			if (order[i].equals(s))
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * Works out the built-in rule, group and rank for an item.
	 *
	 * @param name        item name
	 * @param equipable   whether the item can be worn
	 * @param stats       equipment stats, may be null
	 * @param actions     inventory actions, entries may be null
	 * @param storePrice  shop value, used as a rough tier
	 */
	static ItemInfo classify(int id, String name, boolean equipable, ItemEquipmentStats stats, String[] actions, int storePrice)
	{
		String n = name.toLowerCase();
		String base = baseName(n);
		int suffix = suffixNumber(n);
		boolean eat = false, drink = false;
		if (actions != null)
		{
			for (String a : actions)
			{
				if ("Eat".equals(a))
				{
					eat = true;
				}
				else if ("Drink".equals(a))
				{
					drink = true;
				}
			}
		}
		boolean combat = equipable && hasCombatStats(stats);
		int slot = stats != null ? stats.getSlot() : -1;

		Rule rule;
		int group = 0;
		int rank = 0;
		String family = "";

		if (MONEY_EXACT.contains(base) || CLUE.matcher(n).find())
		{
			rule = Rule.MONEY;
			group = base.equals("coins") || base.equals("platinum token") ? 0 : clueTier(n);
		}
		else if (base.equals("rune pouch") || base.equals("divine rune pouch"))
		{
			rule = Rule.RUNES;
			group = AMMO_POUCH;
		}
		else if (RUNE.matcher(base).matches())
		{
			rule = Rule.RUNES;
			group = AMMO_RUNES;
			int i = indexOf(RUNE_ORDER, base);
			rank = i < 0 ? RUNE_ORDER.length : i;
		}
		else if (slot == EquipmentInventorySlot.AMMO.getSlotIdx() && !base.contains("blessing") && !base.contains("book")
			|| equipable && THROWN.matcher(n).find())
		{
			rule = Rule.RUNES;
			group = ammoType(base);
			rank = ammoRank(group, base, storePrice);
		}
		else if (SKILL_CAPE.matcher(n).matches())
		{
			rule = Rule.TELEPORTS;
			group = 0;
		}
		else if (startsWithAny(base, TELEPORT_JEWELLERY))
		{
			// each kind of jewellery together, most charges first
			rule = Rule.TELEPORTS;
			group = 1;
			rank = startIndex(base, TELEPORT_JEWELLERY) * 1000 - suffix;
		}
		else if (!equipable && (n.contains("teleport") || n.contains("tablet")))
		{
			rule = Rule.TELEPORTS;
			group = 2;
		}
		else if (startsWithAny(base, TELEPORT_ITEMS) || hasTeleportAction(actions, equipable))
		{
			// diary rewards, capes and anything else with a teleport option; listed ones first, the rest by name
			rule = Rule.TELEPORTS;
			group = 3;
			rank = startIndex(base, TELEPORT_ITEMS);
		}
		else if (toolType(n, base) >= 0)
		{
			// by skill; within a skill: tools, then the outfit, then storage (bags, pouches)
			rule = Rule.SKILLING;
			int type = toolType(n, base);
			group = toolSkill(type, base) * 100 + (type == TOOL_STORAGE ? 50 : type);
			rank = toolRank(type, base, storePrice);
		}
		else if (!equipable && SKILL_ITEMS.containsKey(base))
		{
			// skill rewards (marks of grace, stardust...) after the skill's tools, outfit and storage
			rule = Rule.SKILLING;
			group = SKILL_ITEMS.get(base) * 100 + SKILL_ITEMS_GROUP;
		}
		else if (equipable && containsAny(n, OUTFITS))
		{
			// with its skill's tools; each set together, pieces from head to boots
			rule = Rule.SKILLING;
			int set = outfitSet(n);
			group = OUTFIT_SKILL.getOrDefault(OUTFITS.get(set), SKILL_OTHER) * 100 + OUTFITS_GROUP;
			rank = set * 10 + outfitPiece(slot);
		}
		else if (drink && suffix >= 1 && suffix <= 4 && !equipable)
		{
			// potions not in the list go after it, by name; doses of one potion stay together
			rule = Rule.POTIONS;
			int i = indexOf(POTION_ORDER, base);
			group = i < 0 ? POTION_ORDER.length : i;
		}
		else if (eat || drink)
		{
			rule = Rule.FOOD;
			Integer heal = FOOD_HEAL.get(base);
			rank = -(heal != null ? heal * 1000 : Math.min(storePrice, 999));
		}
		else if (combat)
		{
			rule = Rule.GEAR;
		}
		else if (equipable)
		{
			rule = Rule.COSMETIC;
			group = slot;
			family = headNoun(base);
			rank = tierOrPrice(prefixTier(base, METALS), METALS.length, 0);
		}
		else if (resourceGroup(n, base) >= 0)
		{
			// by skill, keeping each skill's types in their own order
			rule = Rule.RESOURCES;
			int type = resourceGroup(n, base);
			group = resourceSkill(type) * 100 + type;
			rank = resourceRank(type, base, storePrice);
			if (type == GROUP_CONTAINERS)
			{
				// each kind of container together, the empty one first
				family = headNoun(base);
				rank = CONTAINERS.contains(base) ? 0 : 1;
			}
		}
		else
		{
			// similar names together (all cannonballs, all pages), metal ones by tier
			rule = Rule.MISC;
			group = 0;
			family = headNoun(base);
			rank = tierOrPrice(prefixTier(base, METALS), METALS.length, 0);
		}

		return new ItemInfo(id, name, base, suffix, rule, group, rank, storePrice, stats, family);
	}

	/**
	 * True if one of the item's options teleports: any option with "teleport" in it, or "Rub" on wearable
	 * jewellery (lamps are rubbed too, but can't be worn).
	 */
	static boolean hasTeleportAction(String[] actions, boolean equipable)
	{
		if (actions == null)
		{
			return false;
		}
		for (String a : actions)
		{
			if (a == null)
			{
				continue;
			}
			if (a.toLowerCase().contains("teleport") || equipable && a.equals("Rub"))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean isAxe(String n)
	{
		return AXE.matcher(n).find() && !n.contains("battleaxe") && !n.contains("thrownaxe");
	}

	private static int clueTier(String n)
	{
		if (n.contains("beginner"))
		{
			return 1;
		}
		if (n.contains("easy"))
		{
			return 2;
		}
		if (n.contains("medium"))
		{
			return 3;
		}
		if (n.contains("hard"))
		{
			return 4;
		}
		if (n.contains("elite"))
		{
			return 5;
		}
		if (n.contains("master"))
		{
			return 6;
		}
		return 7;
	}

	private static int startIndex(String base, List<String> list)
	{
		for (int i = 0; i < list.size(); i++)
		{
			if (base.startsWith(list.get(i)))
			{
				return i;
			}
		}
		return list.size();
	}

	/**
	 * Index of the entry the name starts with as a whole word (the longest one), or -1.
	 * "adamant" also matches "adamantite" and "rune" matches "runite".
	 */
	static int prefixTier(String n, String[] order)
	{
		int best = -1;
		for (int i = 0; i < order.length; i++)
		{
			String p = order[i];
			boolean match = n.startsWith(p + " ")
				|| p.equals("adamant") && n.startsWith("adamantite ")
				|| p.equals("rune") && n.startsWith("runite ");
			if (match && (best < 0 || p.length() > order[best].length()))
			{
				best = i;
			}
		}
		return best;
	}

	/**
	 * Groups without a fixed tier order, where items are grouped by the words they share with other items
	 * in the bank. Groups with their own order (ores, herbs, gems, runes, gear...) keep it.
	 */
	static boolean isLoose(Rule rule, int group)
	{
		switch (rule)
		{
			case MONEY:
			case FOOD:
			case COSMETIC:
			case MISC:
				return true;
			case POTIONS:
				return group == POTION_ORDER.length;
			case TELEPORTS:
				// the listed teleport items (group 3) keep the list's order
				return group == 0 || group == 2;
			case RUNES:
				return group == AMMO_OTHER || group == AMMO_CHINCHOMPAS;
			case SKILLING:
				return group % 100 == TOOL_OTHER || group % 100 == SKILL_ITEMS_GROUP;
			case RESOURCES:
				switch (group % 100)
				{
					case GROUP_OTHER_SEEDS:
					case GROUP_FARMING:
					case GROUP_SECONDARIES:
					case GROUP_HIDES:
					case GROUP_CRAFTING:
					case GROUP_BONES:
					case GROUP_ASHES:
					case GROUP_ENSOULED:
					case GROUP_RAW_FOOD:
					case GROUP_CONTAINERS:
						return true;
					default:
						return false;
				}
			default:
				return false;
		}
	}

	private static final List<String> STOP_WORDS = Arrays.asList("of", "the", "and", "with", "for");

	/**
	 * The words of a name that can link it to other items: no brackets, numbers or little words.
	 */
	static List<String> words(String base)
	{
		List<String> out = new java.util.ArrayList<>();
		for (String w : base.replaceAll("\\(.*?\\)", " ").split("[^a-z0-9'+-]+"))
		{
			if (w.length() >= 3 && !STOP_WORDS.contains(w) && !w.matches("[0-9/+-]+"))
			{
				out.add(w);
			}
		}
		return out;
	}

	/**
	 * The main word of a name: the last word, ignoring anything in brackets and trailing numbers,
	 * without a plural "s". "Granite cannonball" and "Cannonball" both give "cannonball".
	 */
	static String headNoun(String base)
	{
		String b = base.replaceAll("\\(.*?\\)", " ").trim();
		// "bucket of sand" is a bucket, "ring of wealth" a ring
		int of = b.indexOf(" of ");
		if (of > 0)
		{
			b = b.substring(0, of);
		}
		String[] words = b.split("\\s+");
		// "burnt shark", "broken pickaxe": the state word groups them
		if (words.length > 1 && PREFIX_FAMILIES.contains(words[0]))
		{
			return words[0];
		}
		int i = words.length - 1;
		while (i > 0 && words[i].matches("\\d+|[ivx]+"))
		{
			i--;
		}
		String w = words[i];
		if (w.length() > 3 && w.endsWith("s") && !w.endsWith("ss"))
		{
			w = w.substring(0, w.length() - 1);
		}
		return w;
	}

	/**
	 * The metal an item is made of ("rune", "dragon"...), or null.
	 */
	static String metalOf(String base)
	{
		int i = prefixTier(base, METALS);
		return i < 0 ? null : METALS[i];
	}

	private static int tierOrPrice(int tier, int listLength, int storePrice)
	{
		return tier >= 0 ? tier : listLength + Math.min(storePrice, 1_000_000);
	}

	static int ammoType(String base)
	{
		if (base.endsWith("arrow") || base.endsWith("arrows"))
		{
			return AMMO_ARROWS;
		}
		if (base.endsWith("bolts") || base.endsWith("bolt"))
		{
			return AMMO_BOLTS;
		}
		if (base.endsWith("javelin"))
		{
			return AMMO_JAVELINS;
		}
		if (base.endsWith("dart"))
		{
			return AMMO_DARTS;
		}
		if (base.endsWith("knife"))
		{
			return AMMO_KNIVES;
		}
		if (base.endsWith("thrownaxe"))
		{
			return AMMO_THROWNAXES;
		}
		if (base.contains("chinchompa"))
		{
			return AMMO_CHINCHOMPAS;
		}
		return AMMO_OTHER;
	}

	private static int ammoRank(int type, String base, int storePrice)
	{
		if (type == AMMO_BOLTS)
		{
			// metal bolts first, then gem-tipped bolts by gem, each with its dragon version straight after
			int gem = prefixTier(base, GEM_ORDER);
			if (gem >= 0)
			{
				return 100 + gem * 2 + (base.contains("dragon bolts") ? 1 : 0);
			}
			return tierOrPrice(prefixTier(base, METALS), METALS.length, storePrice);
		}
		if (type == AMMO_OTHER || type == AMMO_CHINCHOMPAS)
		{
			return storePrice;
		}
		return tierOrPrice(prefixTier(base, METALS), METALS.length, storePrice);
	}

	static int toolSkill(int type, String base)
	{
		switch (type)
		{
			case TOOL_AXES:
				return SKILL_WOODCUTTING;
			case TOOL_PICKAXES:
				return SKILL_MINING;
			case TOOL_HARPOONS:
			case TOOL_FISHING:
				return SKILL_FISHING;
			case TOOL_FARMING:
				return SKILL_FARMING;
			case TOOL_HUNTER:
				return SKILL_HUNTER;
			default:
				return TOOL_SKILL.getOrDefault(base, SKILL_OTHER);
		}
	}

	static int resourceSkill(int type)
	{
		switch (type)
		{
			case GROUP_ALLOTMENT_SEEDS:
			case GROUP_HERB_SEEDS:
			case GROUP_TREE_SEEDS:
			case GROUP_FRUIT_SEEDS:
			case GROUP_OTHER_SEEDS:
			case GROUP_FARMING:
				return SKILL_FARMING;
			case GROUP_GRIMY_HERBS:
			case GROUP_CLEAN_HERBS:
			case GROUP_UNF_POTIONS:
			case GROUP_SECONDARIES:
				return SKILL_HERBLORE;
			case GROUP_ORES:
				return SKILL_MINING;
			case GROUP_BARS:
				return SKILL_SMITHING;
			case GROUP_LOGS:
				return SKILL_WOODCUTTING;
			case GROUP_PLANKS:
				return SKILL_CONSTRUCTION;
			case GROUP_FLETCHING_BASICS:
			case GROUP_ARROWTIPS:
			case GROUP_DART_TIPS:
			case GROUP_JAVELIN_HEADS:
			case GROUP_UNF_BOLTS:
			case GROUP_BOLT_TIPS:
			case GROUP_UNSTRUNG_BOWS:
			case GROUP_LIMBS:
			case GROUP_STOCKS:
				return SKILL_FLETCHING;
			case GROUP_UNCUT_GEMS:
			case GROUP_CUT_GEMS:
			case GROUP_DRAGONHIDE:
			case GROUP_DRAGON_LEATHER:
			case GROUP_HIDES:
			case GROUP_CRAFTING:
				return SKILL_CRAFTING;
			case GROUP_BONES:
			case GROUP_ASHES:
			case GROUP_ENSOULED:
				return SKILL_PRAYER;
			case GROUP_RAW_FOOD:
				return SKILL_COOKING;
			case GROUP_ESSENCE:
			case GROUP_TALISMANS:
			case GROUP_TIARAS:
				return SKILL_RUNECRAFT;
			default:
				return SKILL_OTHER;
		}
	}

	/**
	 * Skilling tool type, or -1 if the item isn't a tool.
	 */
	static int toolType(String n, String base)
	{
		if (base.endsWith("pickaxe"))
		{
			return TOOL_PICKAXES;
		}
		if (isAxe(n))
		{
			return TOOL_AXES;
		}
		if (base.endsWith("harpoon"))
		{
			return TOOL_HARPOONS;
		}
		if (indexOf(FISHING_TOOLS, base) >= 0)
		{
			return TOOL_FISHING;
		}
		if (indexOf(FARMING_TOOLS, base) >= 0)
		{
			return TOOL_FARMING;
		}
		if (indexOf(CRAFTING_TOOLS, base) >= 0)
		{
			return TOOL_CRAFTING;
		}
		if (indexOf(HUNTER_TOOLS, base) >= 0)
		{
			return TOOL_HUNTER;
		}
		if (indexOf(STORAGE, base) >= 0)
		{
			return TOOL_STORAGE;
		}
		return SKILLING_TOOLS.contains(base) ? TOOL_OTHER : -1;
	}

	private static int toolRank(int type, String base, int storePrice)
	{
		switch (type)
		{
			case TOOL_AXES:
				// felling axes straight after the matching axe
				return tierOrPrice(prefixTier(base, METALS), METALS.length, storePrice) * 2 + (base.contains("felling") ? 1 : 0);
			case TOOL_PICKAXES:
			case TOOL_HARPOONS:
				return tierOrPrice(prefixTier(base, METALS), METALS.length, storePrice);
			case TOOL_FISHING:
				return indexOf(FISHING_TOOLS, base);
			case TOOL_FARMING:
				return indexOf(FARMING_TOOLS, base);
			case TOOL_CRAFTING:
				return indexOf(CRAFTING_TOOLS, base);
			case TOOL_HUNTER:
				return indexOf(HUNTER_TOOLS, base);
			case TOOL_STORAGE:
				return indexOf(STORAGE, base);
			default:
				return 0;
		}
	}

	/**
	 * Tier inside a resource type; anything not listed goes after, by shop price.
	 */
	static int resourceRank(int group, String base, int storePrice)
	{
		switch (group)
		{
			case GROUP_ALLOTMENT_SEEDS:
				return indexOf(ALLOTMENT_SEEDS, base);
			case GROUP_HERB_SEEDS:
				return indexOf(HERB_SEEDS, base);
			case GROUP_TREE_SEEDS:
				return indexOf(TREE_SEEDS, base);
			case GROUP_FRUIT_SEEDS:
				return indexOf(FRUIT_SEEDS, base);
			case GROUP_GRIMY_HERBS:
				return HERBS.indexOf(base.substring(6));
			case GROUP_CLEAN_HERBS:
				return HERBS.indexOf(base);
			case GROUP_UNF_POTIONS:
				return tierOrPrice(herbIndex(base), HERBS.size(), storePrice);
			case GROUP_SECONDARIES:
				return SECONDARIES.indexOf(base);
			case GROUP_ORES:
				return tierOrPrice(indexOf(ORE_ORDER, base), ORE_ORDER.length, storePrice);
			case GROUP_BARS:
				return tierOrPrice(indexOf(BAR_ORDER, base), BAR_ORDER.length, storePrice);
			case GROUP_LOGS:
				return tierOrPrice(indexOf(LOG_ORDER, base), LOG_ORDER.length, storePrice);
			case GROUP_PLANKS:
				return tierOrPrice(indexOf(PLANK_ORDER, base), PLANK_ORDER.length, storePrice);
			case GROUP_FLETCHING_BASICS:
				return indexOf(FLETCHING_BASICS, base);
			case GROUP_ARROWTIPS:
			case GROUP_DART_TIPS:
			case GROUP_JAVELIN_HEADS:
			case GROUP_UNF_BOLTS:
			case GROUP_LIMBS:
				return tierOrPrice(prefixTier(base, METALS), METALS.length, storePrice);
			case GROUP_BOLT_TIPS:
				return tierOrPrice(prefixTier(base, GEM_ORDER), GEM_ORDER.length, storePrice);
			case GROUP_UNSTRUNG_BOWS:
				// shortbow then longbow for each wood, plain wood first
				return (prefixTier(base, WOODS) + 1) * 2 + (base.contains("longbow") ? 1 : 0);
			case GROUP_STOCKS:
				return prefixTier(base, WOODS) + 1;
			case GROUP_UNCUT_GEMS:
				return indexOf(GEM_ORDER, base.substring(6));
			case GROUP_CUT_GEMS:
				return indexOf(GEM_ORDER, base);
			case GROUP_DRAGONHIDE:
			case GROUP_DRAGON_LEATHER:
				return tierOrPrice(prefixTier(base, DRAGONHIDE_COLOURS), DRAGONHIDE_COLOURS.length, storePrice);
			case GROUP_TALISMANS:
			case GROUP_TIARAS:
				return tierOrPrice(indexOf(ALTAR_ORDER, base.substring(0, base.lastIndexOf(' '))), ALTAR_ORDER.length, storePrice);
			default:
				// bones, ashes, raw food and the rest: shop price is a fair tier
				return storePrice;
		}
	}

	/**
	 * Herb tier for an unfinished potion, e.g. "ranarr potion" is ranarr weed.
	 */
	private static int herbIndex(String base)
	{
		String herb = base.endsWith(" potion") ? base.substring(0, base.length() - 7) : base;
		for (int i = 0; i < HERBS.size(); i++)
		{
			if (HERBS.get(i).startsWith(herb))
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * Resource type, roughly by skill. Returns -1 for items that aren't resources.
	 */
	static int resourceGroup(String n, String base)
	{
		if (indexOf(HERB_SEEDS, base) >= 0)
		{
			return GROUP_HERB_SEEDS;
		}
		if (indexOf(ALLOTMENT_SEEDS, base) >= 0)
		{
			return GROUP_ALLOTMENT_SEEDS;
		}
		if (indexOf(TREE_SEEDS, base) >= 0)
		{
			return GROUP_TREE_SEEDS;
		}
		if (indexOf(FRUIT_SEEDS, base) >= 0)
		{
			return GROUP_FRUIT_SEEDS;
		}
		if (n.contains("seed") || n.contains("sapling"))
		{
			return GROUP_OTHER_SEEDS;
		}
		if (n.contains("compost") || n.equals("plant pot") || n.equals("filled plant pot"))
		{
			return GROUP_FARMING;
		}
		if (n.startsWith("grimy ") && HERBS.contains(base.substring(6)))
		{
			return GROUP_GRIMY_HERBS;
		}
		if (HERBS.contains(base))
		{
			return GROUP_CLEAN_HERBS;
		}
		if (n.endsWith("(unf)") && !n.contains("bolt"))
		{
			return GROUP_UNF_POTIONS;
		}
		if (SECONDARIES.contains(base))
		{
			return GROUP_SECONDARIES;
		}
		if (CONTAINERS.contains(headNoun(base)) && (CONTAINERS.contains(base) || base.contains(" of ")))
		{
			return GROUP_CONTAINERS;
		}
		if (n.endsWith(" ore") || n.equals("coal") || n.equals("amethyst") || n.contains("nugget"))
		{
			return GROUP_ORES;
		}
		if (n.endsWith(" bar") || n.equals("elemental metal"))
		{
			return GROUP_BARS;
		}
		if (n.endsWith("logs") || n.equals("bark"))
		{
			return GROUP_LOGS;
		}
		if (n.endsWith("plank"))
		{
			return GROUP_PLANKS;
		}
		if (indexOf(FLETCHING_BASICS, base) >= 0)
		{
			return GROUP_FLETCHING_BASICS;
		}
		if (n.endsWith("arrowtips"))
		{
			return GROUP_ARROWTIPS;
		}
		if (n.endsWith("dart tip"))
		{
			return GROUP_DART_TIPS;
		}
		if (n.endsWith("javelin heads"))
		{
			return GROUP_JAVELIN_HEADS;
		}
		if (n.contains("bolts (unf)") || n.contains("unfinished bolts"))
		{
			return GROUP_UNF_BOLTS;
		}
		if (n.endsWith("bolt tips"))
		{
			return GROUP_BOLT_TIPS;
		}
		if (n.endsWith("bow (u)"))
		{
			return GROUP_UNSTRUNG_BOWS;
		}
		if (n.endsWith(" limbs"))
		{
			return GROUP_LIMBS;
		}
		if (n.endsWith(" stock"))
		{
			return GROUP_STOCKS;
		}
		if (n.startsWith("uncut ") && GEMS.contains(base.substring(6)))
		{
			return GROUP_UNCUT_GEMS;
		}
		if (GEMS.contains(base))
		{
			return GROUP_CUT_GEMS;
		}
		if (n.endsWith("dragonhide"))
		{
			return GROUP_DRAGONHIDE;
		}
		if (n.endsWith("dragon leather"))
		{
			return GROUP_DRAGON_LEATHER;
		}
		if (n.contains("hide") || n.contains("leather"))
		{
			return GROUP_HIDES;
		}
		if (n.equals("molten glass") || n.equals("bucket of sand") || n.equals("soda ash") || n.contains("seaweed")
			|| n.equals("ball of wool") || n.equals("wool") || n.contains("clay") || n.equals("gold leaf")
			|| n.equals("marble block") || n.equals("limestone brick") || n.startsWith("unpowered orb"))
		{
			return GROUP_CRAFTING;
		}
		if (n.contains("bones"))
		{
			return GROUP_BONES;
		}
		if (n.endsWith(" ashes"))
		{
			return GROUP_ASHES;
		}
		if (n.startsWith("ensouled") || n.endsWith(" remains"))
		{
			return GROUP_ENSOULED;
		}
		if (n.startsWith("raw ") || n.equals("pot of flour") || n.equals("bucket of milk") || n.equals("egg")
			|| n.equals("grapes") || n.equals("cheese"))
		{
			return GROUP_RAW_FOOD;
		}
		if (n.contains("essence"))
		{
			return GROUP_ESSENCE;
		}
		if (n.endsWith(" talisman"))
		{
			return GROUP_TALISMANS;
		}
		if (n.endsWith(" tiara"))
		{
			return GROUP_TIARAS;
		}
		return -1;
	}
}

package com.banksteward;

import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemEquipmentStats;

/**
 * Orders items inside a tab: by category (in list order), then by each category's own rules.
 */
final class ItemSorter
{
	private static final int STYLE_MELEE = 0;
	private static final int STYLE_RANGED = 1;
	private static final int STYLE_MAGIC = 2;
	private static final int STYLE_OTHER = 3;

	private ItemSorter()
	{
	}

	/**
	 * @param categoryOrder category id to its position in the category list
	 */
	static Comparator<BankItem> comparator(Map<String, Integer> categoryOrder, BankStewardConfig.GearSort gearSort)
	{
		return comparator(categoryOrder, gearSort, Collections.emptyList());
	}

	/**
	 * @param categoryOrder category id to its position in the category list
	 * @param bank          the whole bank, used to order gear sets by their strongest piece and give each set one style
	 */
	static Comparator<BankItem> comparator(Map<String, Integer> categoryOrder, BankStewardConfig.GearSort gearSort,
		Collection<BankItem> bank)
	{
		return comparator(categoryOrder, gearSort, bank, Collections.emptyMap());
	}

	/**
	 * @param alchProfits profit per cast from Alch Ledger, by item id; items in the High alch category go best first
	 */
	static Comparator<BankItem> comparator(Map<String, Integer> categoryOrder, BankStewardConfig.GearSort gearSort,
		Collection<BankItem> bank, Map<Integer, Integer> alchProfits)
	{
		GearContext gear = new GearContext(bank);
		WordGroups words = new WordGroups(bank);
		Comparator<BankItem> gearOrder = gearSort == BankStewardConfig.GearSort.STYLE
			? gear.bySet()
			: Comparator.comparingInt((BankItem b) -> slotOrder(b.getInfo().getStats()))
				.thenComparingInt(b -> style(b.getInfo()))
				.thenComparingInt(b -> -score(b.getInfo()));

		Comparator<BankItem> order = Comparator
			.comparingInt((BankItem b) -> b.getCategory() == null
				? Integer.MAX_VALUE
				: categoryOrder.getOrDefault(b.getCategory().getId(), Integer.MAX_VALUE))
			.thenComparingInt(b -> b.getCategory() != null && CategoryStore.HIGH_ALCH.equals(b.getCategory().getId())
				? -alchProfits.getOrDefault(b.getInfo().getId(), Integer.MIN_VALUE + 1)
				: 0)
			.thenComparingInt(b -> b.getInfo().getRule().ordinal())
			.thenComparing((x, y) -> x.getInfo().getRule() == Rule.GEAR && y.getInfo().getRule() == Rule.GEAR
				? gearOrder.compare(x, y)
				: 0)
			.thenComparingInt(b -> b.getInfo().getRule() == Rule.GEAR ? 0 : b.getInfo().getGroup())
			.thenComparingInt(b -> words.loose(b) ? words.clusterRank(b) : 0)
			.thenComparing(b -> words.loose(b) ? words.cluster(b) : b.getInfo().getFamily())
			.thenComparingInt(b -> b.getInfo().getRule() == Rule.GEAR ? 0 : b.getInfo().getRank())
			.thenComparing(b -> b.getInfo().getBaseName())
			.thenComparingInt(b -> -b.getInfo().getSuffixNumber());

		// Items with exactly the same name (recolours, clue steps...) sort as one item, so they always sit together
		Map<String, BankItem> byName = new HashMap<>();
		for (BankItem b : bank)
		{
			byName.merge(b.getInfo().getName().toLowerCase(), b,
				(x, y) -> x.getInfo().getId() <= y.getInfo().getId() ? x : y);
		}
		// Items used with each other (a secondary and its unfinished potion, a chisel and uncut gems) sit
		// together when they share a tab
		UsedTogether together = new UsedTogether(bank, order);
		return Comparator
			.comparing((BankItem b) ->
			{
				BankItem a = together.anchor(b);
				return byName.getOrDefault(a.getInfo().getName().toLowerCase(), a);
			}, order)
			.thenComparingInt(together::offset)
			.thenComparingInt(b -> b.getInfo().getId())
			.thenComparingInt(BankItem::getItemId);
	}

	/**
	 * Groups items by the words they share with other items in the bank, so things go together even when
	 * there's no rule for them: "Silver sickle" and "Silver sickle (b)", every "Bucket of ...", all "Burnt" food.
	 * Only used where a category has no fixed order of its own. Each item joins the group of its word that the
	 * most other items share. Food and resource groups are ordered by their best member, others A-Z.
	 */
	private static final class WordGroups
	{
		private final Map<String, String> clusterByName = new HashMap<>();
		private final Map<String, Integer> clusterRank = new HashMap<>();

		WordGroups(Collection<BankItem> bank)
		{
			// how many differently named items in each block share each word
			Map<String, Map<String, Integer>> counts = new HashMap<>();
			Map<String, BankItem> byName = new HashMap<>();
			for (BankItem b : bank)
			{
				if (loose(b))
				{
					byName.putIfAbsent(b.getInfo().getName().toLowerCase(), b);
				}
			}
			for (BankItem b : byName.values())
			{
				Map<String, Integer> c = counts.computeIfAbsent(block(b), k -> new HashMap<>());
				for (String w : new java.util.LinkedHashSet<>(ItemRules.words(b.getInfo().getBaseName())))
				{
					c.merge(w, 1, Integer::sum);
				}
			}
			for (Map.Entry<String, BankItem> e : byName.entrySet())
			{
				BankItem b = e.getValue();
				Map<String, Integer> c = counts.get(block(b));
				String head = ItemRules.headNoun(b.getInfo().getBaseName());
				String best = null;
				int bestCount = 1;
				int bestPos = -1;
				java.util.List<String> ws = ItemRules.words(b.getInfo().getBaseName());
				for (int i = 0; i < ws.size(); i++)
				{
					String w = ws.get(i);
					int n = c.getOrDefault(w, 0);
					// most shared word wins; on a tie the main word, then the later word
					boolean better = n > bestCount
						|| n == bestCount && best != null && (w.equals(head) && !best.equals(head)
							|| !best.equals(head) && i > bestPos);
					if (n >= 2 && better)
					{
						best = w;
						bestCount = n;
						bestPos = i;
					}
				}
				String cluster = block(b) + "|" + (best != null ? best : head);
				clusterByName.put(e.getKey(), cluster);
			}
			for (BankItem b : bank)
			{
				if (loose(b))
				{
					clusterRank.merge(cluster(b), b.getInfo().getRank(), Math::min);
				}
			}
		}

		private static String block(BankItem b)
		{
			String category = b.getCategory() == null ? "" : b.getCategory().getId();
			return category + "|" + b.getInfo().getRule() + "|" + b.getInfo().getGroup();
		}

		boolean loose(BankItem b)
		{
			return ItemRules.isLoose(b.getInfo().getRule(), b.getInfo().getGroup());
		}

		String cluster(BankItem b)
		{
			return clusterByName.getOrDefault(b.getInfo().getName().toLowerCase(),
				block(b) + "|" + ItemRules.headNoun(b.getInfo().getBaseName()));
		}

		/**
		 * Food groups go best healing first and resource groups by tier; elsewhere groups go A-Z.
		 */
		int clusterRank(BankItem b)
		{
			Rule rule = b.getInfo().getRule();
			if (rule != Rule.FOOD && rule != Rule.RESOURCES)
			{
				return 0;
			}
			return clusterRank.getOrDefault(cluster(b), b.getInfo().getRank());
		}
	}

	private static final int SECTION_WEAPONS = 0;
	private static final int SECTION_ARMOUR = 1;
	private static final int SECTION_ACCESSORIES = 2;

	/**
	 * Gear is grouped into weapons (by kind, e.g. all scimitars), armour (by set, e.g. all rune pieces)
	 * and accessories (amulets, rings, capes, ammo-slot items). Each family gets one combat style, worked out
	 * from all its pieces, so a set never gets split, and families are ordered strongest first.
	 */
	private static final class GearContext
	{
		private final Map<String, int[]> styleTotals = new HashMap<>();
		private final Map<String, Integer> best = new HashMap<>();

		GearContext(Collection<BankItem> bank)
		{
			for (BankItem b : bank)
			{
				if (b.getInfo().getRule() != Rule.GEAR)
				{
					continue;
				}
				ItemInfo info = b.getInfo();
				String family = family(info);
				int[] totals = styleTotals.computeIfAbsent(family, k -> new int[4]);
				totals[style(info)] += Math.max(1, score(info));
				best.merge(family, score(info), Math::max);
			}
		}

		int familyStyle(ItemInfo info)
		{
			if (section(info) == SECTION_ACCESSORIES)
			{
				return style(info);
			}
			int[] totals = styleTotals.get(family(info));
			if (totals == null)
			{
				return style(info);
			}
			// the style most of the set's strength is in; "other" only if nothing else
			int pick = STYLE_OTHER;
			for (int st = STYLE_MELEE; st <= STYLE_MAGIC; st++)
			{
				if (totals[st] > 0 && (pick == STYLE_OTHER || totals[st] > totals[pick]))
				{
					pick = st;
				}
			}
			return pick;
		}

		Comparator<BankItem> bySet()
		{
			return Comparator
				.comparingInt((BankItem b) -> familyStyle(b.getInfo()))
				.thenComparingInt(b -> section(b.getInfo()))
				.thenComparingInt(b -> section(b.getInfo()) == SECTION_ACCESSORIES
					? slotOrder(b.getInfo().getStats())
					: -best.getOrDefault(family(b.getInfo()), score(b.getInfo())))
				.thenComparing(b -> family(b.getInfo()))
				.thenComparingInt(b -> pieceOrder(b.getInfo().getStats()))
				.thenComparingInt(b -> -score(b.getInfo()));
		}
	}

	/**
	 * Which block of a category an item belongs to: its armour set or weapon kind for gear,
	 * its type and similar-name group for everything else. Items with the same key sit together.
	 */
	static String blockKey(BankItem b)
	{
		String category = b.getCategory() == null ? "" : b.getCategory().getId();
		ItemInfo info = b.getInfo();
		if (info.getRule() == Rule.GEAR)
		{
			return category + "|gear|" + section(info) + "|" + family(info);
		}
		return category + "|" + info.getRule() + "|" + info.getGroup() + "|" + info.getFamily();
	}

	static int section(ItemInfo info)
	{
		ItemEquipmentStats s = info.getStats();
		int slot = s == null ? -1 : s.getSlot();
		if (slot == EquipmentInventorySlot.WEAPON.getSlotIdx())
		{
			return SECTION_WEAPONS;
		}
		if (slot == EquipmentInventorySlot.AMULET.getSlotIdx() || slot == EquipmentInventorySlot.RING.getSlotIdx()
			|| slot == EquipmentInventorySlot.CAPE.getSlotIdx() || slot == EquipmentInventorySlot.AMMO.getSlotIdx())
		{
			return SECTION_ACCESSORIES;
		}
		return SECTION_ARMOUR;
	}

	/**
	 * Weapons: their kind ("scimitar", "godsword", "2h sword"). Armour: its set ("rune", "dharok's",
	 * "black d'hide"). Accessories: their slot.
	 */
	static String family(ItemInfo info)
	{
		String base = info.getBaseName();
		switch (section(info))
		{
			case SECTION_WEAPONS:
			{
				// "silver sickle (b)" is a sickle
				String w = base.replaceAll("\\(.*?\\)", " ").trim();
				int of = w.indexOf(" of ");
				if (of > 0)
				{
					w = w.substring(0, of);
				}
				if (w.endsWith("2h sword"))
				{
					return "2h sword";
				}
				int space = w.lastIndexOf(' ');
				return space < 0 ? w : w.substring(space + 1);
			}
			case SECTION_ACCESSORIES:
				return "slot " + slotOrder(info.getStats());
			default:
			{
				int hide = base.indexOf("d'hide");
				if (hide >= 0)
				{
					return base.substring(0, hide + 6);
				}
				String metal = ItemRules.metalOf(base);
				if (metal != null)
				{
					return metal;
				}
				int space = base.indexOf(' ');
				return space < 0 ? base : base.substring(0, space);
			}
		}
	}

	/**
	 * Armour pieces in the order a set is usually laid out.
	 */
	static int pieceOrder(ItemEquipmentStats s)
	{
		int slot = s == null ? -1 : s.getSlot();
		if (slot == EquipmentInventorySlot.HEAD.getSlotIdx())
		{
			return 0;
		}
		if (slot == EquipmentInventorySlot.BODY.getSlotIdx())
		{
			return 1;
		}
		if (slot == EquipmentInventorySlot.LEGS.getSlotIdx())
		{
			return 2;
		}
		if (slot == EquipmentInventorySlot.SHIELD.getSlotIdx())
		{
			return 3;
		}
		if (slot == EquipmentInventorySlot.GLOVES.getSlotIdx())
		{
			return 4;
		}
		if (slot == EquipmentInventorySlot.BOOTS.getSlotIdx())
		{
			return 5;
		}
		return 6;
	}

	static int style(ItemEquipmentStats s)
	{
		if (s == null)
		{
			return STYLE_OTHER;
		}
		int melee = Math.max(s.getAstab(), Math.max(s.getAslash(), s.getAcrush())) + s.getStr();
		int ranged = s.getArange() + s.getRstr();
		int magic = s.getAmagic() + Math.round(s.getMdmg() * 3);
		if (magic > 0 && magic >= melee && magic >= ranged)
		{
			return STYLE_MAGIC;
		}
		if (ranged > 0 && ranged >= melee)
		{
			return STYLE_RANGED;
		}
		if (melee > 0)
		{
			return STYLE_MELEE;
		}
		// pure defence: plate armour has negative magic and ranged attack
		if (s.getAmagic() < 0 || s.getArange() < 0)
		{
			return STYLE_MELEE;
		}
		return STYLE_OTHER;
	}

	static int slotOrder(ItemEquipmentStats s)
	{
		if (s == null)
		{
			return 11;
		}
		int slot = s.getSlot();
		if (slot == EquipmentInventorySlot.WEAPON.getSlotIdx())
		{
			return 0;
		}
		if (slot == EquipmentInventorySlot.SHIELD.getSlotIdx())
		{
			return 1;
		}
		if (slot == EquipmentInventorySlot.HEAD.getSlotIdx())
		{
			return 2;
		}
		if (slot == EquipmentInventorySlot.BODY.getSlotIdx())
		{
			return 3;
		}
		if (slot == EquipmentInventorySlot.LEGS.getSlotIdx())
		{
			return 4;
		}
		if (slot == EquipmentInventorySlot.GLOVES.getSlotIdx())
		{
			return 5;
		}
		if (slot == EquipmentInventorySlot.BOOTS.getSlotIdx())
		{
			return 6;
		}
		if (slot == EquipmentInventorySlot.AMULET.getSlotIdx())
		{
			return 7;
		}
		if (slot == EquipmentInventorySlot.RING.getSlotIdx())
		{
			return 8;
		}
		if (slot == EquipmentInventorySlot.CAPE.getSlotIdx())
		{
			return 9;
		}
		if (slot == EquipmentInventorySlot.AMMO.getSlotIdx())
		{
			return 10;
		}
		return 11;
	}

	private static final java.util.regex.Pattern MAGIC_WEAPON = java.util.regex.Pattern.compile(
		"(staff|wand|sceptre|trident|sanguinesti|tumeken's shadow|kodai|nightmare staff|harmonised|volatile|eldritch)");
	private static final java.util.regex.Pattern RANGED_WEAPON = java.util.regex.Pattern.compile(
		"(bow|blowpipe|ballista|dart|knife|thrownaxe|javelin|chinchompa|atlatl)");

	/**
	 * Combat style of an item. Weapons are judged by what they are first, because stats can mislead:
	 * many staves have more crush and strength than magic attack, but they're still magic weapons.
	 */
	static int style(ItemInfo info)
	{
		ItemEquipmentStats s = info.getStats();
		if (s != null && s.getSlot() == EquipmentInventorySlot.WEAPON.getSlotIdx())
		{
			String n = info.getBaseName();
			if (MAGIC_WEAPON.matcher(n).find())
			{
				return STYLE_MAGIC;
			}
			if (RANGED_WEAPON.matcher(n).find())
			{
				return STYLE_RANGED;
			}
		}
		return style(s);
	}

	static int score(ItemInfo info)
	{
		return score(info.getStats(), style(info));
	}

	private static int score(ItemEquipmentStats s, int style)
	{
		if (s == null)
		{
			return 0;
		}
		int defence = s.getDstab() + s.getDslash() + s.getDcrush() + s.getDmagic() + s.getDrange();
		int offence;
		switch (style)
		{
			case STYLE_MAGIC:
				offence = s.getAmagic() + Math.round(s.getMdmg() * 3);
				break;
			case STYLE_RANGED:
				offence = s.getArange() + s.getRstr();
				break;
			default:
				offence = Math.max(s.getAstab(), Math.max(s.getAslash(), s.getAcrush())) + s.getStr();
		}
		return offence * 5 + defence + s.getPrayer() * 3;
	}
}

package com.banksteward;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Category colour markers on bank items, and a dashed box on items in the wrong tab.
 */
class MarkerOverlay extends WidgetItemOverlay
{
	private static final Color WRONG_TAB = new Color(255, 70, 70, 220);
	private static final Color TAB_ICON = new Color(255, 200, 60, 230);
	private static final Stroke DASHED = new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f, new float[]{3f, 2f}, 0f);

	private final BankStewardPlugin plugin;
	private final BankStewardConfig config;

	@Inject
	MarkerOverlay(BankStewardPlugin plugin, BankStewardConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		showOnBank();
	}

	@Override
	public void renderItemOverlay(Graphics2D g, int itemId, WidgetItem widgetItem)
	{
		BankItem item = plugin.itemAtSlot(widgetItem.getWidget().getIndex());
		if (item == null || item.getItemId() != itemId)
		{
			// tag tab layouts put items in other widgets, so look it up by id
			item = plugin.itemById(itemId);
			if (item == null)
			{
				return;
			}
		}

		Rectangle r = widgetItem.getCanvasBounds();
		Category category = item.getCategory();
		BankStewardConfig.MarkerStyle style = config.markerStyle();
		if (config.showCategoryMarkers() && category != null && style != BankStewardConfig.MarkerStyle.NONE)
		{
			g.setColor(Fade.category(category.getColor(), config.categoryOpacity()));
			switch (style)
			{
				case CORNER:
					// bottom-right, clear of the quantity number in the top-left
					Polygon corner = new Polygon();
					corner.addPoint(r.x + r.width, r.y + r.height);
					corner.addPoint(r.x + r.width - 9, r.y + r.height);
					corner.addPoint(r.x + r.width, r.y + r.height - 9);
					g.fillPolygon(corner);
					break;
				case BAR:
					g.fillRect(r.x + 1, r.y + r.height - 2, r.width - 2, 2);
					break;
				case OUTLINE:
					g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
					break;
				default:
					break;
			}
		}

		Planner.Plan plan = plugin.getPlan();
		if (config.highlightTabIcons() && plan != null && !plugin.isTagTabOpen()
			&& plan.getTabIcons().contains(item.getSlot()))
		{
			// reserved as the tab's icon: gold frame and a gold corner in the top-right
			g.setColor(Fade.of(TAB_ICON));
			g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
			Polygon corner = new Polygon();
			corner.addPoint(r.x + r.width, r.y);
			corner.addPoint(r.x + r.width - 9, r.y);
			corner.addPoint(r.x + r.width, r.y + 9);
			g.fillPolygon(corner);
		}

		if (config.markMisplaced() && plan != null && !plugin.isTagTabOpen()
			&& plan.getWrongTab().contains(item.getSlot()))
		{
			Stroke old = g.getStroke();
			g.setStroke(DASHED);
			g.setColor(Fade.of(WRONG_TAB));
			g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
			g.setStroke(old);
		}
	}
}

package com.banksteward;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Value;

/**
 * Works out how far the bank is from its organised layout, and the single best next move.
 * Pure logic so it can be unit tested. It's re-run after every bank change, so a move the
 * player does differently just leads to a different next step.
 */
final class Planner
{
	enum StepType
	{
		/**
		 * Drag {@code item} onto the header of {@code tab} (0 is the All tab, numTabs+1 the new-tab slot).
		 */
		MOVE_TO_TAB,
		/**
		 * Drag {@code item} onto the item at {@code targetSlot} (insert mode).
		 */
		REORDER,
		/**
		 * Open {@code tab} (0 is the All tab).
		 */
		OPEN_TAB,
		DONE
	}

	@Value
	static class Step
	{
		StepType type;
		BankItem item;
		int tab;
		int targetSlot;
		boolean newTab;
	}

	@Value
	static class Plan
	{
		Step next;
		/**
		 * Items in the wrong tab plus items out of order inside their tab.
		 */
		int outOfPlace;
		/**
		 * Slots of items that belong in a different tab.
		 */
		Set<Integer> wrongTab;
		/**
		 * Slots of the tab icons left alone (the first item of each tab), when keeping them.
		 */
		Set<Integer> tabIcons;
		List<String> warnings;
	}

	private Planner()
	{
	}

	static Plan plan(List<BankItem> items, int[] tabSizes, int viewTab, Comparator<BankItem> order)
	{
		return plan(items, tabSizes, viewTab, order, false);
	}

	/**
	 * @param items        bank items in slot order
	 * @param tabSizes     item counts for tabs 1-9 (index 0 unused)
	 * @param viewTab      the tab being viewed, 0 for All
	 * @param keepTabIcons leave the first item of tabs 1-9 alone, since it's the tab's icon
	 */
	static Plan plan(List<BankItem> items, int[] tabSizes, int viewTab, Comparator<BankItem> order, boolean keepTabIcons)
	{
		// A tab's icon is its first item: with keepTabIcons it never moves and everything else sorts after it
		Set<Integer> icons = new HashSet<>();
		if (keepTabIcons)
		{
			int seenTab = 0;
			for (BankItem b : items)
			{
				if (b.getTab() > 0 && b.getTab() != seenTab)
				{
					icons.add(b.getSlot());
					seenTab = b.getTab();
				}
			}
		}

		int numTabs = 0;
		while (numTabs < 9 && tabSizes[numTabs + 1] > 0)
		{
			numTabs++;
		}

		List<String> warnings = new ArrayList<>();
		Set<Integer> wrongTab = new HashSet<>();
		List<BankItem> feasible = new ArrayList<>();
		Set<Integer> blockedTabs = new HashSet<>();
		for (BankItem b : items)
		{
			int target = b.targetTab();
			if (target == b.getTab() || icons.contains(b.getSlot()))
			{
				continue;
			}
			wrongTab.add(b.getSlot());
			if (target <= numTabs + 1)
			{
				feasible.add(b);
			}
			else
			{
				blockedTabs.add(target);
			}
		}
		for (int t : blockedTabs)
		{
			warnings.add("Tab " + t + " can't be made until tab " + (t - 1) + " exists. Give a category tab "
				+ (numTabs + 1) + ", or move the category to a lower tab.");
		}

		// Tab-by-tab: items that stay in their tab, and how many are out of order
		Set<Integer> leaving = new HashSet<>();
		for (BankItem b : feasible)
		{
			leaving.add(b.getSlot());
		}
		Map<Integer, List<BankItem>> staying = new HashMap<>();
		for (BankItem b : items)
		{
			if (!leaving.contains(b.getSlot()) && !icons.contains(b.getSlot()))
			{
				staying.computeIfAbsent(b.getTab(), k -> new ArrayList<>()).add(b);
			}
		}
		int outOfPlace = feasible.size();
		// With a kept icon, the icon's own group (its armour set, its kind of food...) comes straight after it,
		// so the icon doesn't split its group from the rest
		Map<Integer, Comparator<BankItem>> orderByTab = new HashMap<>();
		for (BankItem b : items)
		{
			if (icons.contains(b.getSlot()))
			{
				String block = ItemSorter.blockKey(b);
				orderByTab.put(b.getTab(), Comparator
					.comparing((BankItem x) -> !ItemSorter.blockKey(x).equals(block))
					.thenComparing(order));
			}
		}

		Map<Integer, int[]> lisByTab = new HashMap<>();
		for (Map.Entry<Integer, List<BankItem>> e : staying.entrySet())
		{
			int[] ranks = ranks(e.getValue(), orderByTab.getOrDefault(e.getKey(), order));
			int[] lis = lis(ranks);
			lisByTab.put(e.getKey(), lis);
			outOfPlace += ranks.length - lis.length;
		}

		Step next = nextCrossTabMove(feasible, tabSizes, numTabs, viewTab);
		if (next == null)
		{
			next = nextReorder(staying, lisByTab, viewTab, order, orderByTab);
		}
		return new Plan(next, outOfPlace, wrongTab, icons, warnings);
	}

	private static Step nextCrossTabMove(List<BankItem> feasible, int[] tabSizes, int numTabs, int viewTab)
	{
		if (feasible.isEmpty())
		{
			return null;
		}
		// Fill low tabs first so new tabs get made in order; main tab moves last
		List<BankItem> sorted = new ArrayList<>(feasible);
		sorted.sort(Comparator
			.comparingInt((BankItem b) -> b.targetTab() == 0 ? 10 : b.targetTab())
			.thenComparingInt(BankItem::getSlot));

		// Moving the last item out of a tab deletes it and renumbers the tabs after it, so avoid that while we can
		BankItem best = null;
		BankItem fallback = null;
		boolean anyHidden = false;
		for (BankItem b : sorted)
		{
			boolean visible = viewTab == 0 || b.getTab() == viewTab;
			if (!visible)
			{
				anyHidden = true;
				continue;
			}
			boolean emptiesTab = b.getTab() > 0 && tabSizes[b.getTab()] == 1;
			if (!emptiesTab)
			{
				best = b;
				break;
			}
			if (fallback == null)
			{
				fallback = b;
			}
		}
		if (best == null && anyHidden)
		{
			// the All tab shows everything, so moves without the tab problem may be there
			return new Step(StepType.OPEN_TAB, null, 0, -1, false);
		}
		if (best == null)
		{
			best = fallback;
		}
		int target = best.targetTab();
		return new Step(StepType.MOVE_TO_TAB, best, target, -1, target == numTabs + 1);
	}

	private static Step nextReorder(Map<Integer, List<BankItem>> staying,
		Map<Integer, int[]> lisByTab, int viewTab, Comparator<BankItem> order, Map<Integer, Comparator<BankItem>> orderByTab)
	{
		// the viewed tab first, then tabs 1-9, then the main section
		List<Integer> tabOrder = new ArrayList<>();
		tabOrder.add(viewTab);
		for (int t = 1; t <= 9; t++)
		{
			tabOrder.add(t);
		}
		tabOrder.add(0);

		for (int t : tabOrder)
		{
			List<BankItem> current = staying.get(t);
			if (current == null || lisByTab.get(t).length == current.size())
			{
				continue;
			}
			if (viewTab != t)
			{
				return new Step(StepType.OPEN_TAB, null, t, -1, false);
			}
			return reorderStep(current, lisByTab.get(t), orderByTab.getOrDefault(t, order));
		}
		return new Step(StepType.DONE, null, -1, -1, false);
	}

	private static Step reorderStep(List<BankItem> current, int[] lis, Comparator<BankItem> order)
	{
		int[] ranks = ranks(current, order);
		Set<Integer> inLis = new HashSet<>();
		for (int i : lis)
		{
			inLis.add(i);
		}

		// The lowest-ranked item that's out of order goes straight after its sorted predecessor
		int move = -1;
		for (int i = 0; i < ranks.length; i++)
		{
			if (!inLis.contains(i) && (move < 0 || ranks[i] < ranks[move]))
			{
				move = i;
			}
		}
		int pred = -1;
		for (int i : lis)
		{
			if (ranks[i] < ranks[move] && (pred < 0 || ranks[i] > ranks[pred]))
			{
				pred = i;
			}
		}

		// In insert mode, dropping onto slot j leaves the dragged item at index j
		int j = pred < 0 ? 0 : (pred < move ? pred + 1 : pred);
		BankItem item = current.get(move);
		BankItem target = current.get(j);
		return new Step(StepType.REORDER, item, item.getTab(), target.getSlot(), false);
	}

	/**
	 * Each item's position in the sorted order, listed in current order.
	 */
	static int[] ranks(List<BankItem> current, Comparator<BankItem> order)
	{
		List<BankItem> sorted = new ArrayList<>(current);
		sorted.sort(order);
		Map<Integer, Integer> rankBySlot = new HashMap<>();
		for (int i = 0; i < sorted.size(); i++)
		{
			rankBySlot.put(sorted.get(i).getSlot(), i);
		}
		int[] ranks = new int[current.size()];
		for (int i = 0; i < ranks.length; i++)
		{
			ranks[i] = rankBySlot.get(current.get(i).getSlot());
		}
		return ranks;
	}

	/**
	 * Indices of a longest increasing subsequence, in order. These items can stay put.
	 */
	static int[] lis(int[] a)
	{
		int n = a.length;
		int[] tails = new int[n];
		int[] prev = new int[n];
		int len = 0;
		for (int i = 0; i < n; i++)
		{
			int lo = 0, hi = len;
			while (lo < hi)
			{
				int mid = (lo + hi) >>> 1;
				if (a[tails[mid]] < a[i])
				{
					lo = mid + 1;
				}
				else
				{
					hi = mid;
				}
			}
			prev[i] = lo > 0 ? tails[lo - 1] : -1;
			tails[lo] = i;
			if (lo == len)
			{
				len++;
			}
		}
		int[] out = new int[len];
		int k = len > 0 ? tails[len - 1] : -1;
		for (int i = len - 1; i >= 0; i--)
		{
			out[i] = k;
			k = prev[k];
		}
		return out;
	}

}

package com.banksteward;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Built-in categories. The id doubles as the default category id, so deleting a
 * default category just sends its items to Misc (or leaves them unassigned).
 */
@Getter
@RequiredArgsConstructor
enum Rule
{
	MONEY("money", "Money & clues", 0xF2C14E, Category.MAIN_TAB),
	GEAR("gear", "Gear", 0xE05555, 1),
	TELEPORTS("teleports", "Teleports", 0x4FA3F7, 2),
	RUNES("runes", "Runes & ammo", 0xB57BFF, 3),
	POTIONS("potions", "Potions", 0x3FD1C4, 4),
	FOOD("food", "Food", 0xF08A3C, 5),
	SKILLING("skilling", "Skilling", 0x7BC96F, 6),
	RESOURCES("resources", "Resources", 0xA67C52, 7),
	COSMETIC("cosmetic", "Cosmetic", 0xF27BC1, 8),
